-- Migración 0032. RBAC: PERMISOS, ROLES, ROLES_PERMISOS y USUARIOS_ROLES.
-- Semillas: admin (todos los permisos), empacador y embarque.
-- El usuario ADMIN queda ligado al rol admin.
-- No editar este archivo. El siguiente cambio va en una migración nueva
-- y debe reflejarse en db/init.sql.

BEGIN;

CREATE TABLE "PERMISOS" (
  "ID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "CODIGO" text NOT NULL UNIQUE,
  "NOMBRE" text NOT NULL,
  "DESCRIPCION" text,
  "ACTIVO" boolean NOT NULL DEFAULT true,
  "ES_SEMILLA" boolean NOT NULL DEFAULT false,
  "CREADO_EN" timestamptz NOT NULL DEFAULT now(),
  "ACTUALIZADO_EN" timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE "ROLES" (
  "ID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "CODIGO" text NOT NULL UNIQUE,
  "NOMBRE" text NOT NULL,
  "DESCRIPCION" text,
  "ACTIVO" boolean NOT NULL DEFAULT true,
  "ES_SEMILLA" boolean NOT NULL DEFAULT false,
  "CREADO_EN" timestamptz NOT NULL DEFAULT now(),
  "ACTUALIZADO_EN" timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE "ROLES_PERMISOS" (
  "ID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ROL_ID" integer NOT NULL,
  "PERMISO_ID" integer NOT NULL,
  "ES_SEMILLA" boolean NOT NULL DEFAULT false,
  "CREADO_EN" timestamptz NOT NULL DEFAULT now(),
  "ACTUALIZADO_EN" timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT "ROLES_PERMISOS_ROL_ID_FK"
    FOREIGN KEY ("ROL_ID") REFERENCES "ROLES" ("ID"),
  CONSTRAINT "ROLES_PERMISOS_PERMISO_ID_FK"
    FOREIGN KEY ("PERMISO_ID") REFERENCES "PERMISOS" ("ID"),
  CONSTRAINT "ROLES_PERMISOS_PAR_UQ" UNIQUE ("ROL_ID", "PERMISO_ID")
);

CREATE INDEX "ROLES_PERMISOS_PERMISO_ID_IDX"
  ON "ROLES_PERMISOS" ("PERMISO_ID");

CREATE TABLE "USUARIOS_ROLES" (
  "ID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "USUARIO_ID" integer NOT NULL,
  "ROL_ID" integer NOT NULL,
  "ES_SEMILLA" boolean NOT NULL DEFAULT false,
  "CREADO_EN" timestamptz NOT NULL DEFAULT now(),
  "ACTUALIZADO_EN" timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT "USUARIOS_ROLES_USUARIO_ID_FK"
    FOREIGN KEY ("USUARIO_ID") REFERENCES "USUARIOS" ("ID"),
  CONSTRAINT "USUARIOS_ROLES_ROL_ID_FK"
    FOREIGN KEY ("ROL_ID") REFERENCES "ROLES" ("ID"),
  CONSTRAINT "USUARIOS_ROLES_PAR_UQ" UNIQUE ("USUARIO_ID", "ROL_ID")
);

CREATE INDEX "USUARIOS_ROLES_ROL_ID_IDX"
  ON "USUARIOS_ROLES" ("ROL_ID");

CREATE TRIGGER "PERMISOS_ACTUALIZADO_TRG"
  BEFORE UPDATE ON "PERMISOS"
  FOR EACH ROW
  EXECUTE FUNCTION marcar_actualizado_en();

CREATE TRIGGER "ROLES_ACTUALIZADO_TRG"
  BEFORE UPDATE ON "ROLES"
  FOR EACH ROW
  EXECUTE FUNCTION marcar_actualizado_en();

CREATE TRIGGER "ROLES_PERMISOS_ACTUALIZADO_TRG"
  BEFORE UPDATE ON "ROLES_PERMISOS"
  FOR EACH ROW
  EXECUTE FUNCTION marcar_actualizado_en();

CREATE TRIGGER "USUARIOS_ROLES_ACTUALIZADO_TRG"
  BEFORE UPDATE ON "USUARIOS_ROLES"
  FOR EACH ROW
  EXECUTE FUNCTION marcar_actualizado_en();

