INSERT INTO "ROLES" ("ID", "CODIGO", "NOMBRE", "DESCRIPCION", "ES_SEMILLA") VALUES
  (1, 'admin', 'Administrador', 'Acceso completo a todos los permisos', true),
  (2, 'empacador', 'Almacenista Empaque', 'Opera lotes, productos, referencias y origen', true),
  (3, 'embarque', 'Almacenista Embarque', 'Opera expediciones, embarques, recepciones y unidades', true);

-- Admin: todos los permisos.
INSERT INTO "ROLES_PERMISOS" ("ROL_ID", "PERMISO_ID", "ES_SEMILLA")
SELECT 1, p."ID", true
FROM "PERMISOS" AS p;

-- Empacador: lectura de todo.
INSERT INTO "ROLES_PERMISOS" ("ROL_ID", "PERMISO_ID", "ES_SEMILLA")
SELECT 2, p."ID", true
FROM "PERMISOS" AS p
WHERE p."CODIGO" LIKE '%.leer';

-- Empacador: crear/editar en dominio de empaque.
INSERT INTO "ROLES_PERMISOS" ("ROL_ID", "PERMISO_ID", "ES_SEMILLA")
SELECT 2, p."ID", true
FROM "PERMISOS" AS p
WHERE p."CODIGO" IN (
  'lotes.crear',
  'lotes.editar',
  'lotes_productos.crear',
  'lotes_productos.editar',
  'lotes_referencias.crear',
  'lotes_referencias.editar',
  'lotes_ubicaciones.crear',
  'lotes_ubicaciones.editar'
);

-- Embarque: lectura de todo.
INSERT INTO "ROLES_PERMISOS" ("ROL_ID", "PERMISO_ID", "ES_SEMILLA")
SELECT 3, p."ID", true
FROM "PERMISOS" AS p
WHERE p."CODIGO" LIKE '%.leer';

-- Embarque: crear/editar en dominio de embarque/recepción.
INSERT INTO "ROLES_PERMISOS" ("ROL_ID", "PERMISO_ID", "ES_SEMILLA")
SELECT 3, p."ID", true
FROM "PERMISOS" AS p
WHERE p."CODIGO" IN (
  'expediciones.crear',
  'expediciones.editar',
  'expediciones_lotes.crear',
  'expediciones_lotes.editar',
  'recepciones.crear',
  'recepciones.editar',
  'recepciones_lotes.crear',
  'recepciones_lotes.editar',
  'unidades_transporte.crear',
  'unidades_transporte.editar'
);

INSERT INTO "USUARIOS_ROLES" ("ID", "USUARIO_ID", "ROL_ID", "ES_SEMILLA") VALUES
