SELECT setval(pg_get_serial_sequence('"PERMISOS"', 'ID'), (SELECT MAX("ID") FROM "PERMISOS"));
SELECT setval(pg_get_serial_sequence('"ROLES"', 'ID'), (SELECT MAX("ID") FROM "ROLES"));
SELECT setval(
  pg_get_serial_sequence('"ROLES_PERMISOS"', 'ID'),
  (SELECT MAX("ID") FROM "ROLES_PERMISOS")
);
SELECT setval(
  pg_get_serial_sequence('"USUARIOS_ROLES"', 'ID'),
  (SELECT MAX("ID") FROM "USUARIOS_ROLES")
);

